parameters.jsCode:
const response = $input.first().json;
const content = response.choices[0].message.content;
let soru;
try {
  soru = JSON.parse(content);
} catch(e) {
  throw new Error('GPT yanıtı JSON parse edilemedi: ' + content);
}

const ders = $('Webhook - Soru Talebi').first().json.body.ders;
const kullanici_id = $('Webhook - Soru Talebi').first().json.body.kullanici_id;
const konu = $('Webhook - Soru Talebi').first().json.body.konu;
const zorluk = $('Webhook - Soru Talebi').first().json.body.zorluk;

return [{
  json: {
    soru_metni: soru.soru_metni,
    secenekler: soru.secenekler,
    dogru_cevap: soru.dogru_cevap,
    cozum_aciklamasi: soru.cozum_aciklamasi,
    konu_etiketi: soru.konu_etiketi || konu,
    zorluk_puani: soru.zorluk_puani || 3,
    ders: ders,
    konu: konu,
    zorluk: zorluk,
    kullanici_id: kullanici_id,
    olusturulma_tarihi: new Date().toISOString(),
    kaynak: 'gpt-4o'
  }
}];

